ActionEntryPtr
ActionEntry::NewSubheading(
    const std::string& value) {
  return ActionEntryPtr(
      std::in_place,
      std::in_place_index<static_cast<size_t>(Tag::kSubheading)>,
      std::move(value));
}

ActionEntryPtr
ActionEntry::NewDetails(
    ActionDetailsPtr value) {
  return ActionEntryPtr(
      std::in_place,
      std::in_place_index<static_cast<size_t>(Tag::kDetails)>,
      std::move(value));
}

ActionEntry::ActionEntry(
    std::in_place_index_t<static_cast<size_t>(Tag::kSubheading)>,
    const std::string& value)
    : tag_(Tag::kSubheading),
      data_(std::in_place_index<static_cast<size_t>(Tag::kSubheading)>,
            std::move(value)) {}

ActionEntry::ActionEntry(
    std::in_place_index_t<static_cast<size_t>(Tag::kDetails)>,
    ActionDetailsPtr value)
    : tag_(Tag::kDetails),
      data_(std::in_place_index<static_cast<size_t>(Tag::kDetails)>,
            std::move(value)) {}
ActionEntry::~ActionEntry() {
  DestroyActive();
}

void ActionEntry::set_subheading(const std::string& subheading) {
  if (tag_ == Tag::kSubheading) {
    data_.subheading = std::move(subheading);
  } else {
    DestroyActive();
    tag_ = Tag::kSubheading;
    new (&data_.subheading) std::string(
        std::move(subheading));
  }
}

void ActionEntry::set_details(ActionDetailsPtr details) {
  if (tag_ == Tag::kDetails) {
    data_.details = std::move(details);
  } else {
    DestroyActive();
    tag_ = Tag::kDetails;
    new (&data_.details) ActionDetailsPtr(
        std::move(details));
  }
}


ActionEntry::Union_::Union_(
    std::in_place_index_t<static_cast<size_t>(Tag::kSubheading)>,
    const std::string& value)
    : subheading(std::move(value)) {}

ActionEntry::Union_::Union_(
    std::in_place_index_t<static_cast<size_t>(Tag::kDetails)>,
    ActionDetailsPtr value)
    : details(std::move(value)) {}

void ActionEntry::DestroyActive() {
  switch (tag_) {

    case Tag::kSubheading:
      std::destroy_at(&data_.subheading);
      break;
    case Tag::kDetails:
      std::destroy_at(&data_.details);
      break;
  }
}
size_t ActionEntry::Hash(size_t seed) const {
  seed = mojo::internal::HashCombine(seed, static_cast<uint32_t>(tag_));
  switch (tag_) {

    case Tag::kSubheading:
      return mojo::internal::Hash(seed, data_.subheading);
    case Tag::kDetails:
      return mojo::internal::Hash(seed, data_.details);
    default:
      NOTREACHED();
  }
}

bool ActionEntry::Validate(
    const void* data,
    mojo::internal::ValidationContext* validation_context) {
  return Data_::Validate(data, validation_context, false);
}
