// static
bool ChatUIStubDispatch::Accept(
    ChatUI* impl,
    mojo::Message* message) {
  switch (static_cast<messages::ChatUI>(message->header()->name)) {
    case messages::ChatUI::kOnNewDefaultConversation: {
      DCHECK(message->is_serialized());
      internal::ChatUI_OnNewDefaultConversation_Params_Data* params =
          reinterpret_cast<internal::ChatUI_OnNewDefaultConversation_Params_Data*>(
              message->mutable_payload());
      

      // Validation for ChatUI.0
      bool success = true;
      std::optional<int32_t> p_content_id{};
      ChatUI_OnNewDefaultConversation_ParamsDataView input_data_view(params, message);
      
      if (success) {
        p_content_id = input_data_view.content_id();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            ChatUI::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->OnNewDefaultConversation(        
        std::move(p_content_id));
      return true;
    }
    case messages::ChatUI::kOnChildFrameBound: {
      DCHECK(message->is_serialized());
      internal::ChatUI_OnChildFrameBound_Params_Data* params =
          reinterpret_cast<internal::ChatUI_OnChildFrameBound_Params_Data*>(
              message->mutable_payload());
      

      // Validation for ChatUI.1
      bool success = true;
      ::mojo::PendingReceiver<::ai_chat::mojom::ParentUIFrame> p_receiver{};
      ChatUI_OnChildFrameBound_ParamsDataView input_data_view(params, message);
      
      if (success) {
        p_receiver =
            input_data_view.TakeReceiver<decltype(p_receiver)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            ChatUI::Name_, 1, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->OnChildFrameBound(        
        std::move(p_receiver));
      return true;
    }
    case messages::ChatUI::kOnDisplayModeChanged: {
      DCHECK(message->is_serialized());
      internal::ChatUI_OnDisplayModeChanged_Params_Data* params =
          reinterpret_cast<internal::ChatUI_OnDisplayModeChanged_Params_Data*>(
              message->mutable_payload());
      

      // Validation for ChatUI.2
      bool success = true;
      bool p_is_standalone{};
      ChatUI_OnDisplayModeChanged_ParamsDataView input_data_view(params, message);
      
      if (success)
        p_is_standalone = input_data_view.is_standalone();
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            ChatUI::Name_, 2, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->OnDisplayModeChanged(        
        std::move(p_is_standalone));
      return true;
    }
  }
  return false;
}

