// static
bool UnionTraits<::ai_chat::mojom::ActionEntry::DataView, ::ai_chat::mojom::ActionEntryPtr>::Read(
    ::ai_chat::mojom::ActionEntry::DataView input,
    ::ai_chat::mojom::ActionEntryPtr* output) {
  using UnionType = ::ai_chat::mojom::ActionEntry;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kSubheading: {
      std::string result_subheading{};
      if (!input.ReadSubheading(&result_subheading))
        return false;

      *output = UnionType::NewSubheading(
          std::move(result_subheading));
      break;
    }
    case Tag::kDetails: {
      ::ai_chat::mojom::ActionDetailsPtr result_details{};
      if (!input.ReadDetails(&result_details))
        return false;

      *output = UnionType::NewDetails(
          std::move(result_details));
      break;
    }
    default:

      return false;
  }
  return true;
}

